head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "test1",
        "col2": "col2",
        "col3": "col3"
    }, {
        "col1": "test2",
        "col2": "col2",
        "col3": "col3"
    }, {
        "col1": "test3",
        "col2": "col2",
        "col3": "col3"
    }]
    dataList1.setJSON(jsonData)
};
scwin.onpageunload = function() {};
scwin.dataList1_onbeforecelldatachange = function(info) {
    console.log(info);
    return false;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#ipt', 'key-sequence', {
        sequence: 'abc'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#ipt', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_2_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt').value = ''");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('ipt').value == 'test3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
 scwin.unitTest();
